describe('Sticky Footer Navigation on Mobile', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
        cy.viewport('iphone-6'); // Set viewport to mobile size
    });

    it('should display sticky footer navigation on mobile', () => {
        cy.get('footer').should('be.visible'); // Ensure footer is visible
        cy.get('footer').should('have.class', 'sticky-footer'); // Check for sticky class
    });

    it('should remain visible when scrolling down', () => {
        cy.scrollTo(0, 500); // Scroll down the page
        cy.get('footer').should('be.visible'); // Footer should still be visible
    });
});
